const fs = require("fs");

function readFile(path, callback) {
  if (!path) return callback(new Error("path required"));
  fs.readFile(path, "utf8", (err, data) => {
    if (err) return callback(err);
    callback(null, data);
  });
}

function mapWith(arr, fn) {
  const out = [];
  for (let i = 0; i < arr.length; i++) {
    out.push(fn(arr[i], i));
  }
  return out;
}

console.log(mapWith([1, 2, 3], (x) => x * 2)); // [2, 4, 6]

function applyTwice(fn, value) {
  return fn(fn(value));
}

console.log(applyTwice((x) => x + 3, 1)); // 7
console.log(applyTwice((x) => x * 2, 5)); // 20

function compose(f, g) {
  return (x) => f(g(x));
}

const double = (x) => x * 2;
const inc = (x) => x + 1;
console.log(compose(double, inc)(5)); // 12  (double(inc(5)))

function onceCallback(fn) {
  let done = false;
  return function (...args) {
    if (done) return;
    done = true;
    return fn.apply(this, args);
  };
}

const warn = onceCallback((msg) => console.warn(msg));
warn("first");
warn("second"); // ignored

function delayCallback(fn, ms, ...args) {
  setTimeout(() => fn(...args), ms);
}

delayCallback((name) => console.log(`hi ${name}`), 1000, "Ada");

function forEachWith(arr, fn) {
  for (let i = 0; i < arr.length; i++) {
    fn(arr[i], i, arr);
  }
}

forEachWith(["a", "b"], (item, i) => console.log(i, item));

function someWith(arr, predicate) {
  for (const item of arr) {
    if (predicate(item)) return true;
  }
  return false;
}

console.log(someWith([1, 2, 3], (n) => n > 2)); // true
console.log(someWith([1, 2], (n) => n > 5)); // false

function curry2(fn) {
  return (a) => (b) => fn(a, b);
}

const mul = curry2((a, b) => a * b);
console.log(mul(3)(4)); // 12

function partial(fn, ...preset) {
  return function (...rest) {
    return fn(...preset, ...rest);
  };
}

const greet = (greeting, name) => `${greeting}, ${name}!`;
const sayHi = partial(greet, "Hi");
console.log(sayHi("Grace")); // "Hi, Grace!"

function callbackToPromise(fn) {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (err, result) => (err ? reject(err) : resolve(result)));
    });
}

const delayedEcho = callbackToPromise((value, cb) => setTimeout(() => cb(null, value), 10));
delayedEcho("ok").then(console.log); // "ok"

