const handlers = new Map();

function registerHandler(eventName, handler) {
  if (!handlers.has(eventName)) handlers.set(eventName, []);
  handlers.get(eventName).push(handler);
}

function emit(eventName, payload) {
  for (const handler of handlers.get(eventName) || []) {
    handler(payload);
  }
}

registerHandler("ping", (data) => console.log("pong", data));
emit("ping", 1); // "pong 1"

function retry(times, fn, callback) {
  fn((err, result) => {
    if (!err || times <= 1) return callback(err, result);
    retry(times - 1, fn, callback);
  });
}

let attempts = 0;
retry(
  3,
  (cb) => {
    attempts++;
    cb(attempts < 3 ? new Error("fail") : null, attempts);
  },
  (err, result) => console.log(err, result) // null 3
);

function memoizeWith(fn, keyFn) {
  const cache = new Map();
  return (...args) => {
    const key = keyFn(...args);
    if (cache.has(key)) return cache.get(key);
    const value = fn(...args);
    cache.set(key, value);
    return value;
  };
}

const byFirstLetter = memoizeWith(
  (s) => s.toUpperCase(),
  (s) => s[0]
);
console.log(byFirstLetter("apple")); // "APPLE"
console.log(byFirstLetter("avocado")); // cached via key "a"

function safeCall(fn, args, onError) {
  try {
    return fn(...args);
  } catch (err) {
    onError(err);
    return undefined;
  }
}

safeCall(
  (a, b) => a / b,
  [10, 0],
  (err) => console.error("caught:", err.message)
);

function pipeline(...fns) {
  return (x) => fns.reduce((acc, fn) => fn(acc), x);
}

const process = pipeline(
  (s) => s.trim(),
  (s) => s.toLowerCase(),
  (s) => s.split(" ").join("-")
);
console.log(process("  Hello World  ")); // "hello-world"
